#include <stdio.h>
#include <stdlib.h>
#include <ascauth.h>

/* Assume 'asce' has been obtained from ASC_INIT() or ASC_INIT_EXT() */
extern ASCENV *asce;   /* provided elsewhere */

void check_user(const char *userid)
{
    int rc = ASC_USER_INCLUDE_EXCLUDE(asce, (char *)userid);

    if (rc == AS_NOMATCH) {
        printf("%s does not match an Include or Exclude statement (default include)\n", userid);
    } else if (rc == AS_INCLUDED) {
        printf("%s matches an Include statement\n", userid);
    } else if (rc == AS_EXCLUDED) {
        printf("%s matches an Exclude statement\n", userid);
    } else if (rc == AS_NOAUTHENV) {
        printf("Authentication environment not established for %s (rc=%d)\n", userid, rc);
    } else {
        printf("Unexpected return code %d for user %s: %s\n", rc, userid, ASC_STRERROR(rc));
    }
}
